import { Border } from "@syncfusion/ej2-react-charts";
import {
  AreaChart,
  ComposedChart,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Area,
  Line,
} from "recharts";

export default function Chartarea() {

  const data = [
    {
      name: 2018,
      uv: 1000,
      pv: 2400,
      amt: 2400,
    },
    {
      name: 2019,
      uv: 3000,
      pv: 1398,
      amt: 2210,
    },
    {
      name: 2020,
      uv: 2000,
      pv: 9800,
      amt: 2290,
    },
    {
      name: 2021,
      uv: 2780,
      pv: 3908,
      amt: 2000,
    },
    {
      name: 2022,
      uv: 1890,
      pv: 4800,
      amt: 2181,
    },
    {
      name: 2023,
      uv: 2390,
      pv: 3800,
      amt: 2500,
    },
    {
      name: 2024,
      uv: 3490,
      pv: 4300,
      amt: 2100,
    },
    {
      name: 2024,
      uv: 3390,
      pv: 300,
      amt: 2100,
    },
  ];

  return (
    <>
      <h2>Area</h2>
      <AreaChart
        width={470}
        height={250}
        data={data}
        margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
        style={{
          backgroundColor: "#3F3F3F",
          color: "red",
          height: "90%",
          width: "100%",
          borderRadius:"10px",
        }}
      >
        <defs>
          <linearGradient id="colorUv" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="#8884d8" stopOpacity={0.8} />
            <stop offset="95%" stopColor="#8884d8" stopOpacity={0} />
          </linearGradient>
          <linearGradient id="colorPv" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="#82ca9d" stopOpacity={0.8} />
            <stop offset="95%" stopColor="#82ca9d" stopOpacity={0} />
          </linearGradient>
        </defs>
        <XAxis dataKey="name" stroke="#fff" />
        <YAxis stroke="#fff" />
        <CartesianGrid stroke="" strokeDasharray="3 3" />
        <Tooltip />
        <Area
          type="monotone"
          dataKey="uv"
          stroke="#8884d8"
          fillOpacity={1}
          fill="url(#colorUv)"
        />
        <Area
          type="monotone"
          dataKey="pv"
          stroke="#82ca9d"
          fillOpacity={1}
          fill="url(#colorPv)"
        />
      </AreaChart>
    </>
  );
}
